template:
otelcol.receiver.filelog "${1:default}" {
  output {
    metrics = []
    logs = []
    traces = []
  }
  debug_metrics {
    $0
  }
  header {
    metadata_operators = "${2}"
    pattern = "${3}"
  }
  multiline {
    line_end_pattern = "${2}"
    line_start_pattern = "${3}"
  }
  ordering_criteria {
    sort_by {
      $0
    }
  }
  retry_on_failure {
  }
}
